    height: 100%;
    transition: 2s
}
div.bg-linear-to-b>.duration-300{
    opacity: 0%;
}
div.bg-linear-to-b:hover>.duration-300{
    opacity: 100%;
}

21456.custom_css:
/* Profile positioning */
body {
  font-size: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* "Edit your profile" button */
.som-button-primary {
  background: #000 !important;
  border: 3px solid #f00;
  border-radius: 16px;
}

/* Profile */
.profile-container :is(h1, h2, h3, p, a) {
  color: #fff !important;
}
.profile-container {
  background: #000 !important;
  margin: 1em;
  border-radius: 16px;
}
.profile-container .card-with-gradient {
  border: 3px solid #f00;
  border-radius: 16px;
}
.profile-container div {
  background: #000 !important;
  color: #fff;
}

/* Profile picture */
.profile-avatar:hover {transform: scale(1.1);}
.profile-avatar {
  width: 120px;
  height: auto;
  border: 2px solid #f00;
  border-radius: 16px;
  filter: drop-shadow(1px 4px 4px #f00);
  transition: transform 0.3s ease;
}
